// Two gates. 1) Code rules that GLiDE can never override. 2) GLiDE judges the rest from the evidence.
const c = $json;
const reason = String($('Start').first().json.reason || '').trim();
if (!c.found) return [{ json: { blocked: c.error } }];
const s = c.snapshot;
const pending = c.case_proposals.filter(p => p.status === 'pending');
const openIncidents = (s.incidents || []).filter(i => !['RESOLVED', 'CLOSED'].includes(i.status));
// A failed booking stops counting once a later plan booked the same kind (ferry, hotel, train, flight).
const steps = c.plan_steps || [];
const rebooked = (p) => /^book_/.test(p.kind) && steps.some(q => q.kind === p.kind && q.status === 'done' && q.id > p.id);
const openSteps = steps.filter(p => p.status === 'waiting_for_person' || (p.status === 'failed' && !rebooked(p)));
const blocks = [];
if (pending.length) blocks.push(`${pending.length} proposal(s) still waiting for a person (#${pending.map(p => p.id).join(', #')})`);
if (openIncidents.length) blocks.push(`open incident(s) ${openIncidents.map(i => `${i.kind} ${i.status}`).join(', ')} need a human owner to resolve`);
if (openSteps.length) blocks.push(`${openSteps.length} plan step(s) still open (${openSteps.map(p => `#${p.id} ${p.kind} ${p.status}`).join(', ')})`);
if (!reason) blocks.push('reason is required: say what was checked and why nothing needs a decision');
if (blocks.length) return [{ json: { blocked: blocks.join('; ') } }];
const state = {
  snapshot_now: s.snapshot_now,
  agent_reason_for_closing: reason,
  order: { ref: c.order_ref, status: s.order.status },
  alerts: (s.alerts || []).map(a => ({ id: a.id, signal: a.signal, severity: a.severity, status: a.status, summary: a.summary })),
  open_work_items: (s.work_items || []).filter(w => w.status !== 'CLOSED').map(w => ({ kind: w.kind, next_action: w.next_action })),
  delivery_windows: (s.time_windows || []).map(w => ({ purpose: w.purpose, start: w.start_at, end: w.end_at })),
  latest_tracking: (s.tracking_latest || []).slice(-1),
  travel_reservations: (s.travel_reservations || []).map(r => ({ route: r.route_label, departs: r.departure_at, cutoff: r.check_in_cutoff_at, state: r.snapshot_journey_state })),
  case_timeline: c.case_timeline.slice(-12).map(t => `${t.actor}: ${t.text}`),
  decided_proposals: c.case_proposals.map(p => ({ id: p.id, action: p.action, status: p.status })),
};
const glide_body = {
  model: 'fastino/GLiDE', store: false, state,
  questions: {
    can_close: {
      type: 'noul',
      instructions: 'Using only the evidence in the state, is every issue on this delivery either resolved or verified fine (for example the driver confirmed position and on-time progress), so that no person needs to decide anything about a booking, delivery date, cost or customer message?',
      criteria: { true: 'Everything is resolved or verified; the case can be closed with a log entry', false: 'Something is unresolved, unverified, at risk of missing a promised time, or needs a human decision' },
    },
  },
};
return [{ json: { blocked: null, glide_body } }];

// ponytail: placeholder threshold from the Settings page; tune on labelled cases before trusting it more.
const THRESHOLD = $('Get context').first().json.settings?.glide_close ?? 0.8;
const a = $json.answers?.can_close;
const ref = $('Get context').first().json.order_ref;
const reason = $('Start').first().json.reason;
if (!a) return [{ json: { close: false, order_ref: ref, reason, verdict: `GLiDE unavailable (${$json.error?.message || 'no answer'}); not closing. Hand to a person instead.` } }];
const p = Number(a.noul);
const close = p >= THRESHOLD;
return [{ json: { close, order_ref: ref, glide_noul: p, glide_confidence: a.confidence, reason,
  verdict: close ? `GLiDE: safe to close (p=${p.toFixed(2)})` : `GLiDE: keep open (p=${p.toFixed(2)} < ${THRESHOLD}); something still needs a person or more evidence.` } }];
